sys_script_include.script:
var Cisco_Secure_Access_Public_Create_Approval_Alert_ = Class.create();
Cisco_Secure_Access_Public_Create_Approval_Alert_.prototype = {
	initialize: function () {
	},

	createApprovalAlerts: function () {
		gs.info("[Cisco Secure Access -  IC] STEP 1: Starting createApprovalAlerts()");
		try {
			// STEP 2: Query discovered applications needing alerts/incidents
			var gr = new GlideRecord('x_1803242_sample_u_discovered_applications_userapp');
			gr.addQuery('u_send_alert', 'No');
			gr.query();

			var totalApps = gr.getRowCount();
			gs.info("[Cisco Secure Access -  IC] STEP 2: Total discovered apps to process: " + totalApps);

			var processedCount = 0;
			var alertsCreated = 0;
			var incidentsCreated = 0;
			var i = 1;
			while (gr.next() && i <= 1) {
				i++;
				processedCount++;
				var weightedRisk = (gr.u_weighted_risk || "").toLowerCase();
				var appName = gr.u_app_name || gr.getValue('name');

				gs.info("[Cisco Secure Access -  IC] STEP 3: Processing app " + processedCount + " of " + totalApps + ": " + appName + " (Weighted Risk: " + weightedRisk + ")");

				// Map weighted risk to severity
				var severityMap = {
					"very high": "1", // Critical
					"high": "2",      // Major
					"medium": "3",    // Minor
					"low": "4",       // Warning
					"very low": "5"   // OK
				};
				var severity = severityMap[weightedRisk] || "0"; // Default to Clear

				// Check for existing alert for this app
				var checkAlert = new GlideRecord('em_alert');
				checkAlert.addQuery('short_description', '[Cisco Secure Access -  IC] - App Approval Alert: ' + appName);
				checkAlert.orderByDesc('sys_created_on');
				checkAlert.setLimit(1);
				checkAlert.query();

				var now = new GlideDateTime();
				var alertExists = false;

				if (checkAlert.next()) {
					var alertStatus = checkAlert.getValue('state');
					var alertCreated = new GlideDateTime(checkAlert.getValue('sys_created_on'));
					var diffMs = GlideDateTime.subtract(now, alertCreated).getNumericValue();
					var diffHours = diffMs / (1000 * 60 * 60);

					if (alertStatus == "Closed" || alertStatus == "No") {
						alertExists = false;
					} 
				}

				if (!alertExists) {
					var alertGR = new GlideRecord('em_alert');
					alertGR.initialize();
					alertGR.short_description = "[Cisco Secure Access -  IC] - App Approval Alert: " + appName;
					alertGR.description =
						"App ID: " + gr.u_app_id + "\n" +
						"Name: " + appName + "\n" +
						"Weighted Risk: " + gr.u_weighted_risk + "\n" +
						"Category: " + gr.u_category + "\n" +
						"Subcategory: " + gr.u_subcategory + "\n" +
						"App Type: " + gr.u_app_type + "\n" +
						"First Detected: " + gr.u_first_detected + "\n" +
						"Last Detected: " + gr.u_last_detected;
					alertGR.severity = severity;
					alertGR.state = "Open";
					alertGR.source = "CSA App Sync";
					alertGR.insert();
					alertsCreated++;
					gs.info("[Cisco Secure Access -  IC] STEP 4: Created alert for app: " + appName);
				}

				// STEP 5: (Commented) Create INCIDENT for weighted risk == high/very high
				/*
				if (weightedRisk === "high" || weightedRisk === "very high") {
					var incGR = new GlideRecord('incident');
					incGR.initialize();
					incGR.short_description = "[Cisco Secure Access -  IC] - App Approval Incident: " + appName;
					incGR.description =
						"App ID: " + gr.u_app_id + "\n" +
						"Name: " + appName + "\n" +
						"Weighted Risk: " + gr.u_weighted_risk + "\n" +
						"Category: " + gr.u_category + "\n" +
						"Subcategory: " + gr.u_subcategory + "\n" +
						"App Type: " + gr.u_app_type + "\n" +
						"First Detected: " + gr.u_first_detected + "\n" +
						"Last Detected: " + gr.u_last_detected;
					incGR.u_status = "Pending";
					incGR.insert();
					incidentsCreated++;
					gs.info("[Cisco Secure Access -  IC] STEP 5: Created incident for app: " + appName);
				}
				*/

				// STEP 6: Update discovered application to mark alert as sent
				gr.u_send_alert = "Yes";
				gr.u_status = "Pending";
				gr.update();
				gs.info("[Cisco Secure Access -  IC] STEP 6: Updated discovered application: " + appName + " marked as alert sent.");
			}

			gs.info("[Cisco Secure Access -  IC] STEP 7: Completed processing " + processedCount + " apps. Alerts created: " + alertsCreated + ", Incidents created: " + incidentsCreated);

		} catch (ex) {
			gs.error('[Cisco Secure Access -  IC] ERROR: ' + ex.message);
			gs.error('[Cisco Secure Access -  IC] ERROR stack: ' + ex.stack);
		}
		gs.info("[Cisco Secure Access -  IC] STEP 8: Finished createApprovalAlerts()");
	},

	type: 'Cisco_Secure_Access_Public_Create_Approval_Alert_'
};
